const UNVERIFIED = 'unverified' as const;

function finish(record: RatingRecord): RatingRecord {
  return applyT83DecisionRow(applyT87uRow(applyT86uRow(applyT83uRow(applyT54uRow(record)))));
}

function flag(name: string, riskLevel: IngredientFlag['riskLevel'], source: string, exempt: boolean): IngredientFlag {
  return exempt ? { name, riskLevel, source, stackCountExempt: true } : { name, riskLevel, source };
}

