const ROWS = BATCH390_KYR6E_T98;
const banned = /is on the Cleared list|is on the Limited list|has its own line|check digit was used|inferred/i;
const ids = new Set<string>();
const upcs = new Set<string>();
function upcCheck(code: string): boolean {
  if (!/^021078\d{6}$/.test(code)) return false;
  const sum = [...code.slice(0, 11)].reduce((total, digit, index) => total + Number(digit) * (index % 2 === 0 ? 3 : 1), 0);
  return (10 - (sum % 10)) % 10 === Number(code[11]);
}
if (ROWS.length !== 420) throw new Error(`batch390 count ${ROWS.length}`);
for (const record of ROWS) {
  const mapped = finish(record);
  if (ids.has(record.id)) throw new Error(`batch390 dup ${record.id}`);
  ids.add(record.id);
  if (!record.barcode || upcs.has(record.barcode) || !upcCheck(record.barcode)) throw new Error(`batch390 upc ${record.id} ${record.barcode}`);
  upcs.add(record.barcode);
  const roll = computeVerdictFromInactiveIngredients(mapped.inactiveIngredients, mapped.activeSafetyFlag);
  if (roll.verdict !== record.verdict || mapped.verdict !== record.verdict) {
    throw new Error(`batch390 verdict ${record.id} ${roll.verdict} ${roll.cause} ${record.verdict}`);
  }
  const counted = mapped.inactiveIngredients.filter((item) => ingredientCountsTowardLimitedStack(item)).map((item) => item.name);
  if (roll.cause === 'limited_stack' && counted.length < 3) throw new Error(`batch390 stack ${record.id}`);
  if ((roll.cause === 'limited_1_2') !== (counted.length === 1 || counted.length === 2)) {
    throw new Error(`batch390 cause ${record.id} ${roll.cause} ${counted.join('|')}`);
  }
  if (roll.cause === 'limited_stack') {
    const sentence = `Avoid: three or more Limited tokens triggered the stacking rule (t137u): ${counted.join(', ')}.`;
    if (!(record.honestNote ?? '').includes(sentence)) throw new Error(`batch390 note ${record.id}`);
  }
  for (const ingredient of mapped.inactiveIngredients) {
    if (isT98ClearedName(ingredient.name) && ingredient.riskLevel !== 'cleared') throw new Error(`batch390 t98 cleared ${ingredient.name}`);
    if (isT98CautionName(ingredient.name) && (ingredient.riskLevel !== 'moderate' || !ingredient.stackCountExempt)) throw new Error(`batch390 t98 caution ${ingredient.name}`);
    const why = plainIngredientWhy(ingredient);
    if (!why || banned.test(why)) throw new Error(`batch390 why ${record.id} ${ingredient.name}: ${why}`);
    if (/That is why it is Usable/i.test(why) && !/This flavor names/i.test(why)) throw new Error(`batch390 usable ${ingredient.name}`);
  }
}

